import assert from 'node:assert/strict';
import { readLines, LineReader } from './src/streaming-utf8/lines.mjs';
import { createRepository } from './src/cursor-pagination/repository.mjs';
import { collectAll } from './src/cursor-pagination/collect.mjs';
import { resolveName } from './src/dependency-aliases/registry.mjs';
import { buildOrder } from './src/dependency-aliases/order.mjs';
import { mergeLayers } from './src/layered-config/merge.mjs';

const encoded = new TextEncoder().encode('A€\r\n\nlast\r');
assert.deepEqual(await readLines([...encoded].map(byte => Uint8Array.of(byte))), ['A€', '', 'last\r']);
const lineReader = new LineReader();
lineReader.feed(new TextEncoder().encode('a\n'));
assert.deepEqual(lineReader.end(), []);

const rows = [{id:1}, {id:2, deleted:true}, {id:3}, {id:4, deleted:true}, {id:5}];
assert.deepEqual(await collectAll(createRepository(rows), {limit:2}), [{id:1}, {id:3}, {id:5}]);
let calls = 0;
await assert.rejects(collectAll({page: async () => { calls++; return {items:[],nextCursor:1}; }}, {maxPages:3}), /Repeated cursor/);
assert.equal(calls, 2);

assert.equal(resolveName('alias1', {real:{}}, {alias1:'alias2', alias2:'real'}), 'real');
assert.deepEqual(buildOrder({nodes:{app:{dependencies:['aliasCore']}, core:{}}, aliases:{aliasCore:'core', another:'core'}}, ['app','another']), ['core','app']);
assert.throws(() => resolveName('a', {}, {a:'b', b:'a'}), /Alias cycle/);
assert.throws(() => buildOrder({nodes:{a:{dependencies:['aliasA']}}, aliases:{aliasA:'a'}}, ['a']), /Dependency cycle/);

const defaults = { endpoint:'base', retries:4, values:{flag:true, zero:7}, list:[{x:1}], untouched:{nested:{v:1}} };
const output = mergeLayers(defaults, {endpoint:'', retries:0, values:{flag:false, zero:null}, list:[{x:2}], untouched:undefined});
assert.deepEqual(output, {endpoint:'', retries:0, values:{flag:false, zero:null}, list:[{x:2}], untouched:{nested:{v:1}}});
assert.notEqual(output.values, defaults.values);
assert.notEqual(output.list, defaults.list);
assert.notEqual(output.list[0], defaults.list[0]);
assert.notEqual(output.untouched, defaults.untouched);
assert.notEqual(output.untouched.nested, defaults.untouched.nested);
assert.equal(defaults.values.flag, true);
console.log('extended contract checks passed');
