function isPlain(value) {
  if (value === null || typeof value !== 'object') return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function setOwn(target, key, value) {
  Object.defineProperty(target, key, {
    value, enumerable: true, writable: true, configurable: true
  });
}

function cloneValue(value) {
  if (Array.isArray(value)) return value.map(cloneValue);
  if (!isPlain(value)) return value;

  const copy = {};
  for (const [key, nested] of Object.entries(value)) {
    if (nested !== undefined) setOwn(copy, key, cloneValue(nested));
  }
  return copy;
}

export function mergeLayers(...layers) {
  const result = {};
  for (const layer of layers) {
    for (const [key, value] of Object.entries(layer)) {
      if (value === undefined) continue;
      const previous = Object.hasOwn(result, key) ? result[key] : undefined;
      const merged = isPlain(value) && isPlain(previous)
        ? mergeLayers(previous, value)
        : cloneValue(value);
      setOwn(result, key, merged);
    }
  }
  return result;
}

